function createEmptyPortfolio(idx) {
  return {
    enabled: idx === 0,
    name: `Portfolio ${idx + 1}`,
    core: [{ asset: "", weight: 0 }],
    stack: [{ asset: "", weight: 0, feeBp: 0, financingBp: 0 }],
    fee: 0,
    result: null,
    dateRange: null,
  };
}

